function playNotification(kind,mode,announce){
  if(mode==='silent'){
    if(S.vibrateWhenSilent&&navigator.vibrate){
      var pattern=kind==='order'?[70,45,70]:kind==='promo'?[45,35,45,35,45]:[55];
      try{navigator.vibrate(pattern)}catch(e){}
    }
    if(announce!==false)toast(S.vibrateWhenSilent?'Mode hening · getar':'Mode hening · tanpa suara');
    return;
  }
  var ctx=ensureAudio();
  if(!ctx){if(announce!==false)toast('Audio tidak tersedia di perangkat ini');return}
  var doPlay=function(){
    if(ctx.state==='suspended'){
      if(announce!==false)toast('Ketuk layar sekali lalu coba lagi');
      return;
    }
    try{
      var now=ctx.currentTime+.06;
      if(mode==='system'){tone(ctx,720,now,.15,'sine',.22);tone(ctx,940,now+.17,.2,'sine',.2)}
      else if(kind==='order'){tone(ctx,523,now,.16,'sine',.25);tone(ctx,659,now+.15,.16,'sine',.25);tone(ctx,784,now+.3,.28,'sine',.22)}
      else if(kind==='promo'){tone(ctx,660,now,.12,'triangle',.22);tone(ctx,990,now+.13,.2,'triangle',.2)}
      else{tone(ctx,880,now,.1,'sine',.22);tone(ctx,880,now+.16,.1,'sine',.22)}
      if(announce!==false)toast(mode==='mimi'?'Bunyi Khas Mimi diputar':'Bunyi pratinjau diputar');
    }catch(err){
      if(announce!==false)toast('Gagal bunyi: '+(err&&err.message?err.message:'error'));
    }
  };
  if(ctx.state==='suspended'){
    try{ctx.resume().then(doPlay).catch(doPlay)}catch(e){doPlay()}
  }else{doPlay()}
}
function bioLoginFlow(role){
  var Bio=window.KasirquhBio;
  if(!Bio)return;
  var status=role==='admin'?$('#adminLoginStatus'):$('#loginAuthStatus');
  function fail(msg){if(status){status.className='auth-status error';status.textContent=msg}}
  Bio.authenticate(role).then(function(cred){
    if(!cred||!cred.email||!cred.password){fail('Gagal membaca sidik jari');return}
    if(status){status.className='auth-status';status.textContent='Sidik jari cocok, menghubungkan…'}
    var loginP=role==='admin'?Store.loginAdmin(cred.email,cred.password):Store.loginCustomer(cred.email,cred.password);
    loginP.then(function(account){
      if(status){status.className='auth-status success';status.textContent='Data cocok'}
      closeSheets();
      if(role==='admin')enterAdminSession('Mode Admin dibuka');
      else finishCustomerLogin(account);
    }).catch(function(err){fail(err&&err.message?err.message:'Masuk gagal')});
  }).catch(function(err){fail(err&&err.message?err.message:'Sidik jari dibatalkan')});
}
function bioRefreshButtons(){
  if(!window.KasirquhBio)return;
  var ab=$('#adminBioLogin'),cb=$('#customerBioLogin'),rb=$('#bioRemoveBtn');
  window.KasirquhBio.isEnrolled('admin').then(function(e){if(ab)ab.hidden=!e});
  window.KasirquhBio.isEnrolled('customer').then(function(e){if(cb)cb.hidden=!e});
  window.KasirquhBio.isEnrolled().then(function(enrolled){
    if(rb)rb.hidden=!enrolled;
    window.KasirquhBio.enrolledEmail('admin').then(function(email){
      var ae=$('#adminLoginEmail');
      if(email&&ae&&!ae.value)ae.placeholder=email;
    });
    window.KasirquhBio.enrolledEmail('customer').then(function(email){
      var ce=$('#loginEmail');
      if(email&&ce&&!ce.value)ce.placeholder=email;
    });
  });
}
/* ---- Pengaturan pelanggan persisten (localStorage) ---- */
var CUSTOMER_PREFS_KEY='kasirquh-customer-prefs';
function saveCustomerPrefs(){
  try{
    localStorage.setItem(CUSTOMER_PREFS_KEY,JSON.stringify({
      theme:S.customerTheme||'light',
      density:($('#customer')&&$('#customer').dataset.density)||'compact',
      sound:S.soundSettings||{order:'system',promo:'system',chat:'system'},
      vibrate:!!S.vibrateWhenSilent
    }));
  }catch(e){}
}
function loadCustomerPrefs(){
  try{
    var raw=localStorage.getItem(CUSTOMER_PREFS_KEY);
    if(!raw)return;
    var p=JSON.parse(raw);
    if(p.theme&&['light','dark','system'].indexOf(p.theme)>=0)S.customerTheme=p.theme;
    if(p.density)$('#customer').dataset.density=p.density;
    if(p.sound){['order','promo','chat'].forEach(function(k){if(typeof p.sound[k]==='string')S.soundSettings[k]=p.sound[k]})}
    if(typeof p.vibrate==='boolean')S.vibrateWhenSilent=p.vibrate;
    // Sinkronkan tampilan tombol aktif
    $$('[data-customer-theme]').forEach(function(b){b.classList.toggle('active',b.dataset.customerTheme===S.customerTheme)});
    $$('[data-density-choice]').forEach(function(b){b.classList.toggle('active',b.dataset.densityChoice===($('#customer').dataset.density||'compact'))});
    applyRoleTheme('customer');
    syncSoundControls();
  }catch(e){}
}
