function purchaseItemParts(item){if(item&&typeof item==='object')return {name:cleanInput(item.name),qty:cleanInput(item.qty)};const text=cleanInput(item);if(text.includes('·')){const parts=text.split('·').map(cleanInput).filter(Boolean);return {name:parts.shift()||'Barang',qty:parts.join(' · ')||'1'}}const match=text.match(/^(.*?)[ ]+(\d+(?:[.,]\d+)?(?:[ ]*(?:pcs|dus|krat|renteng|pak|kg|liter|botol|bungkus|sachet|buah))?)$/i);return match?{name:cleanInput(match[1]),qty:cleanInput(match[2])}:{name:text,qty:'1'}}
function purchaseItemLabel(item){const parts=purchaseItemParts(item);return parts.name+(parts.qty?' · '+parts.qty:'')}
function findPurchaseNote(dateKey,id){return (S.purchaseNotes[dateKey]||[]).find(note=>note.id===id)}
function bindPurchaseNoteCards(){$$('[data-purchase-note]').forEach(card=>{const open=()=>openPurchaseNote(card.dataset.purchaseDate,card.dataset.purchaseNote);card.onclick=open;card.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();open()}}})}
function renderPurchaseNotes(){const notes=S.purchaseNotes[S.activePurchaseDate]||[],total=notes.reduce((sum,note)=>sum+note.total,0);$('#purchaseDateInput').value=S.activePurchaseDate;$('#purchaseDateTitle').textContent=formatPurchaseDate(S.activePurchaseDate);$('#purchaseDayTotal').textContent=notes.length+' catatan · total '+money(total);$('#purchaseNoteList').innerHTML=notes.length?notes.map(note=>`<article class="purchase-note-card" data-purchase-note="${escapeHtml(note.id)}" data-purchase-date="${escapeHtml(S.activePurchaseDate)}" tabindex="0" role="button" aria-label="Buka catatan ${escapeHtml(note.supplier)}"><header><div><h3>${escapeHtml(note.supplier)}</h3><small>${note.items.length} jenis barang</small></div><span class="source-pill">${escapeHtml(note.source==='impor'?'Impor':note.source)}</span></header><ul>${note.items.map(item=>'<li>'+escapeHtml(purchaseItemLabel(item))+'</li>').join('')}</ul><footer><span>Total belanja</span><b>${money(note.total)}</b></footer></article>`).join(''):'<div class="purchase-empty">Belum ada catatan belanja pada tanggal ini.</div>';bindPurchaseNoteCards()}
function renderPurchaseNoteDetail(){if(!S.editingPurchaseNote)return;const note=findPurchaseNote(S.editingPurchaseNote.date,S.editingPurchaseNote.id);if(!note)return;$('#purchaseDetailDate').textContent=formatPurchaseDate(S.editingPurchaseNote.date);$('#purchaseDetailSupplier').textContent=note.supplier;$('#purchaseDetailSource').textContent=note.source;$('#purchaseDetailCount').textContent=note.items.length+' jenis barang';$('#purchaseDetailItems').innerHTML=note.items.map(item=>{const parts=purchaseItemParts(item);return `<div class="purchase-detail-row"><b>${escapeHtml(parts.name)}</b><span>${escapeHtml(parts.qty)}</span></div>`}).join('');$('#purchaseDetailTotal').textContent=money(note.total)}
function showPurchaseDetailMode(){if(!S.editingPurchaseNote)return;renderPurchaseNoteDetail();$('#purchaseDetailView').hidden=false;$('#purchaseEditView').hidden=true;$('#purchaseDeleteConfirm').hidden=true}
function addPurchaseEditRow(item){const parts=purchaseItemParts(item||{name:'',qty:''}),row=document.createElement('div');row.className='purchase-edit-row';const name=document.createElement('input'),qty=document.createElement('input'),remove=document.createElement('button');name.className='purchase-edit-name';name.placeholder='Nama barang';name.setAttribute('aria-label','Nama barang');name.value=parts.name;qty.className='purchase-edit-qty';qty.placeholder='Jumlah';qty.setAttribute('aria-label','Jumlah barang');qty.value=parts.qty;remove.type='button';remove.setAttribute('aria-label','Hapus baris barang');remove.innerHTML='<svg class="icon"><use href="#trash"/></svg>';remove.onclick=()=>{if($('#purchaseEditItems').children.length===1)return toast('Minimal satu barang');row.remove()};row.append(name,qty,remove);$('#purchaseEditItems').append(row)}
function openPurchaseNote(dateKey,id){const note=findPurchaseNote(dateKey,id);if(!note)return;S.editingPurchaseNote={date:dateKey,id:id};showPurchaseDetailMode();openSheet('purchaseNoteModal')}
function openPurchaseNoteEdit(){if(!S.editingPurchaseNote)return;const note=findPurchaseNote(S.editingPurchaseNote.date,S.editingPurchaseNote.id);if(!note)return;$('#purchaseDetailView').hidden=true;$('#purchaseEditView').hidden=false;$('#purchaseEditDate').textContent=formatPurchaseDate(S.editingPurchaseNote.date);$('#purchaseEditSource').textContent=note.source;$('#purchaseEditSupplier').value=note.supplier;$('#purchaseEditTotal').value=groupedNumber(note.total);$('#purchaseEditItems').innerHTML='';note.items.forEach(addPurchaseEditRow);setTimeout(()=>$('#purchaseEditSupplier').focus(),60)}
function savePurchaseNoteEdit(){if(!S.editingPurchaseNote)return;const supplier=cleanInput($('#purchaseEditSupplier').value),rows=$$('#purchaseEditItems .purchase-edit-row'),items=rows.map(row=>({name:cleanInput(row.querySelector('.purchase-edit-name').value),qty:cleanInput(row.querySelector('.purchase-edit-qty').value)})),total=numericValue($('#purchaseEditTotal').value);if(!supplier){$('#purchaseEditSupplier').focus();return toast('Supplier tidak boleh kosong')}if(!items.length)return toast('Tambahkan minimal satu barang');const invalidIndex=items.findIndex(item=>!item.name||!item.qty);if(invalidIndex>=0){rows[invalidIndex].querySelector(!items[invalidIndex].name?'.purchase-edit-name':'.purchase-edit-qty').focus();return toast('Lengkapi nama dan jumlah setiap barang')}if(!total){$('#purchaseEditTotal').focus();return toast('Total belanja harus lebih dari Rp0')}const note=findPurchaseNote(S.editingPurchaseNote.date,S.editingPurchaseNote.id);if(!note)return;note.supplier=supplier;note.items=items;note.total=total;Store.updateStockNote(note.id,{supplier:supplier,items:items,total:total}).catch(error=>{if(!error||error.code!=='OFFLINE')toast(error&&error.message?error.message:'Simpan arsip gagal')});S.activePurchaseDate=S.editingPurchaseNote.date;renderPurchaseNotes();showPurchaseDetailMode();toast('Arsip catatan diperbarui · stok dan keuangan tetap')}
function openPurchaseDeleteConfirm(){if(!S.editingPurchaseNote)return;const note=findPurchaseNote(S.editingPurchaseNote.date,S.editingPurchaseNote.id);if(!note)return;$('#purchaseDetailView').hidden=true;$('#purchaseEditView').hidden=true;$('#purchaseDeleteConfirm').hidden=false;$('#purchaseDeleteSummary').textContent=note.supplier+' · '+money(note.total)+' akan hilang dari arsip '+formatPurchaseDate(S.editingPurchaseNote.date)+'.';setTimeout(()=>$('#cancelPurchaseDelete').focus(),60)}
function deletePurchaseNote(){if(!S.editingPurchaseNote)return;const dateKey=S.editingPurchaseNote.date,notes=S.purchaseNotes[dateKey]||[],index=notes.findIndex(note=>note.id===S.editingPurchaseNote.id);if(index<0)return;const docId=notes[index].id;notes.splice(index,1);S.activePurchaseDate=dateKey;S.editingPurchaseNote=null;closeSheets();renderPurchaseNotes();Store.deleteStockNote(docId).catch(error=>{if(!error||error.code!=='OFFLINE')toast(error&&error.message?error.message:'Hapus arsip gagal')});toast('Catatan dihapus · stok dan keuangan tetap')}
function shiftPurchaseDate(days){const date=new Date(S.activePurchaseDate+'T12:00:00');date.setDate(date.getDate()+days);const pad=n=>String(n).padStart(2,'0');S.activePurchaseDate=date.getFullYear()+'-'+pad(date.getMonth()+1)+'-'+pad(date.getDate());renderPurchaseNotes()}
function addPurchaseRecord(supplier,items,total,source){if(!S.purchaseNotes[S.activePurchaseDate])S.purchaseNotes[S.activePurchaseDate]=[];S.purchaseNotes[S.activePurchaseDate].unshift({id:'purchase-'+Date.now(),supplier:cleanInput(supplier),items:items.map(purchaseItemParts).filter(item=>item.name),total:total,source:source});renderPurchaseNotes()}
function dashboardShortcutById(id){return S.dashboardShortcutCatalog.find(item=>item.id===id)}
function runDashboardShortcut(id){const item=dashboardShortcutById(id);if(!item)return;const action=item.action;if(action.kind==='view')showAdminView(action.value);else if(action.kind==='tab'){showAdminView('data');setDataTab(action.value)}else if(action.kind==='sheet')openSheet(action.value)}
function saveDashboardShortcuts(){storePromise('saveStoreSettings',{dashboardShortcutIds:S.dashboardShortcutIds}).catch(()=>{})}
function renderDashboardShortcuts(){const container=$('#dashboardShortcuts');if(!container)return;container.innerHTML=S.dashboardShortcutIds.map(id=>{const item=dashboardShortcutById(id);if(!item)return '';return `<button class="dashboard-shortcut${S.dashboardShortcutEdit?' is-editing':''}" data-dashboard-shortcut="${item.id}" aria-label="${S.dashboardShortcutEdit?'Hapus ':'Buka '}${escapeHtml(item.label)}">${iconSvg(item.icon)}<b>${escapeHtml(item.label)}</b>${S.dashboardShortcutEdit?'<span class="dashboard-shortcut-remove" aria-hidden="true">×</span>':''}</button>`}).join('')+(S.dashboardShortcutEdit&&S.dashboardShortcutIds.length<6?`<button class="dashboard-shortcut add-shortcut" data-add-dashboard-shortcut aria-label="Tambah shortcut">${iconSvg('grid')}<b>＋ Tambah</b></button>`:'');$$('[data-dashboard-shortcut]').forEach(button=>button.onclick=()=>{if(S.dashboardShortcutEdit){S.dashboardShortcutIds=S.dashboardShortcutIds.filter(id=>id!==button.dataset.dashboardShortcut);saveDashboardShortcuts();renderDashboardShortcuts();renderShortcutPicker();toast('Shortcut dihapus · tersimpan di akun')}else runDashboardShortcut(button.dataset.dashboardShortcut)});const add=$('[data-add-dashboard-shortcut]');if(add)add.onclick=()=>{if(S.dashboardShortcutIds.length>=6)return toast('Maksimal 6 shortcut. Hapus satu terlebih dahulu.');openSheet('shortcutPickerModal')};$('#shortcutEditToggle').textContent=S.dashboardShortcutEdit?'Selesai':'Ubah';$('#shortcutEditToggle').setAttribute('aria-pressed',String(S.dashboardShortcutEdit));$('#shortcutEditNote').hidden=!S.dashboardShortcutEdit;if(S.dashboardShortcutEdit&&S.dashboardShortcutIds.length>=6)$('#shortcutEditNote span').innerHTML='<span class="shortcut-limit">Batas 6 shortcut tercapai.</span> Hapus satu untuk memilih tujuan lain. Susunan tersimpan di akun.';else $('#shortcutEditNote span').textContent='Susunan tersimpan di akun. Hapus lalu tambah lagi untuk mengubah urutan.'}
function renderShortcutPicker(){const list=$('#shortcutPickerList'),status=$('#shortcutPickerStatus');if(!list||!status)return;const groups=[...new Set(S.dashboardShortcutCatalog.map(item=>item.group))],full=S.dashboardShortcutIds.length>=6;list.innerHTML=groups.map(group=>`<section class="shortcut-picker-group"><h3>${escapeHtml(group.toUpperCase())}</h3><div class="shortcut-picker-grid">${S.dashboardShortcutCatalog.filter(item=>item.group===group).map(item=>{const added=S.dashboardShortcutIds.includes(item.id);return `<button class="shortcut-pick" data-pick-shortcut="${item.id}"${added||full?' disabled':''}>${iconSvg(item.icon)}<span><b>${escapeHtml(item.label)}</b><small>${escapeHtml(item.detail)}</small></span><span class="shortcut-pick-state">${added?'Terpasang':full?'Penuh':'＋'}</span></button>`}).join('')}</div></section>`).join('');status.textContent=full?'6 dari 6 terpasang · hapus satu shortcut untuk menambah tujuan lain.':S.dashboardShortcutIds.length+' dari 6 terpasang · pilihan tersimpan di akun.';$$('[data-pick-shortcut]').forEach(button=>button.onclick=()=>{if(S.dashboardShortcutIds.length>=6)return toast('Maksimal 6 shortcut. Hapus satu terlebih dahulu.');if(S.dashboardShortcutIds.includes(button.dataset.pickShortcut))return;S.dashboardShortcutIds.push(button.dataset.pickShortcut);saveDashboardShortcuts();renderDashboardShortcuts();renderShortcutPicker();const item=dashboardShortcutById(button.dataset.pickShortcut);if(S.dashboardShortcutIds.length===6){closeSheets();toast('Shortcut '+item.label+' ditambahkan · batas 6 tercapai')}else toast('Shortcut '+item.label+' ditambahkan')})}
function closeSheets(){stopBarcodeScanner();const resumeGateway=$('#adminPinModal')&&$('#adminPinModal').classList.contains('open')&&$('#gateway').classList.contains('active');$$('.modal').forEach(m=>m.classList.remove('open'));if(resumeGateway)setTimeout(startGateway,0)}
function openSheet(id){closeSheets();if(id==='adminSessionModal')renderSessionInfo();if(id==='transferModal')renderTransfers();if(id==='orderModal')renderActiveOrder();if(id==='priceAlertModal')renderPriceAlerts();if(id==='missionsModal')renderMissions();if(id==='historyModal'||id==='notesModal')renderAccountTiles();if(id==='stockShoppingModal'){renderLowStockSuggestions();updateStockProgress()}if(id==='shortcutPickerModal'){if(S.dashboardShortcutIds.length>=6)return toast('Maksimal 6 shortcut. Hapus satu terlebih dahulu.');renderShortcutPicker()}const modal=$('#'+id);if(modal){formatNumericInputs(modal);modal.classList.add('open')}if(id==='scannerModal')startBarcodeScanner();if(id==='homeControlModal'){const promoSel=$('#promoProductInput'),flashSel=$('#flashProductInput');if(promoSel)promoSel.innerHTML=productOptions(S.promoProductId||'');if(flashSel)flashSel.innerHTML=productOptions(S.flashProductId||'');storeVoid('syncSettingsForms')}if(id==='storeProfileModal'||id==='coinSettingsModal'||id==='adminSettingsModal'){storeVoid('syncSettingsForms')}if(id==='adminSettingsModal'){syncSoundControls();syncNavMotionToggle()}}
function showAdminView(name){closeSheets();$$('.subview').forEach(v=>v.classList.toggle('active',v.id===name+'View'));const primary=['dashboard','kasir','pesanan','note','menu'].includes(name)?name:'menu';$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===primary));if(name==='note')renderPurchaseNotes();if(name==='online')renderOnlineOrders();if(name==='data')renderCustomerData();if(name==='chat')renderAdminChatList();if(name==='bookkeeping'||name==='dashboard'||name==='data')renderFinance();window.scrollTo(0,0)}
function gatewaySlidesCopy(){const gs=S.gatewaySlides||{},fromSettings=k=>cleanInput(gs[k]),fromInput=(id,fb)=>cleanInput($(id)?$(id).value:'')||fb;return [
{kicker:'PROMO UTAMA',title:fromSettings('title1')||fromInput('#gatewayTitle1Input','Hemat belanja, senang di rumah'),copy:fromSettings('copy1')||fromInput('#gatewayCopy1Input','Promo pilihan Warunge Mimi untuk kebutuhan harian keluarga.')},
{kicker:'SEMBAKO',title:fromSettings('title2')||fromInput('#gatewayTitle2Input','Sembako lengkap, tinggal pilih'),copy:fromSettings('copy2')||fromInput('#gatewayCopy2Input','Minyak, gula, mi, dan kebutuhan dapur siap untuk stok rumah.')},
{kicker:'JAJAN & MINUMAN',title:fromSettings('title3')||fromInput('#gatewayTitle3Input','Jajan dan minuman favoritmu'),copy:fromSettings('copy3')||fromInput('#gatewayCopy3Input','Camilan renyah dan minuman segar untuk teman santai kapan saja.')}
]}
function syncGatewayPromo(){showGatewaySlide(S.gatewayIndex,false)}
function stopGatewayTimer(){if(S.gatewayTimer)clearTimeout(S.gatewayTimer);S.gatewayTimer=null}
function showGatewaySlide(index,announce){const slides=gatewaySlidesCopy(),count=slides.length;S.gatewayIndex=(index+count)%count;const item=slides[S.gatewayIndex],gateway=$('#gateway');gateway.classList.add('gateway-content-changing');$$('.gateway-slide').forEach((slide,i)=>slide.classList.toggle('active',i===S.gatewayIndex));$$('[data-gateway-slide]').forEach((dot,i)=>{const active=i===S.gatewayIndex;dot.classList.toggle('active',active);if(active)dot.setAttribute('aria-current','true');else dot.removeAttribute('aria-current')});setTimeout(()=>{$('#gatewayKicker').textContent=item.kicker;$('#gatewayPromoTitle').textContent=item.title;$('#gatewayPromoCopy').textContent=item.copy;gateway.classList.remove('gateway-content-changing')},90);if(announce)$('#gatewayAnnouncement').textContent='Slide '+(S.gatewayIndex+1)+' dari '+count+': '+item.title}
function scheduleGateway(){stopGatewayTimer();S.gatewayTimer=setTimeout(()=>{if(S.gatewayIndex<2){showGatewaySlide(S.gatewayIndex+1,true);scheduleGateway()}else enterGuestCustomer()},4000)}
function advanceGateway(){if(S.gatewayIndex<2){showGatewaySlide(S.gatewayIndex+1,true);scheduleGateway()}else enterGuestCustomer()}
function enterGuestCustomer(){stopGatewayTimer();Store.clearRoleSubs();Store.setGuestSession();go('customer')}
function startGateway(){if(S.sessionRole)return go(S.sessionRole);stopGatewayTimer();S.gatewayIndex=0;showGatewaySlide(0,true);scheduleGateway()}
function go(id){if(id==='gateway'&&S.sessionRole)return go(S.sessionRole);stopGatewayTimer();$$('.screen').forEach(x=>x.classList.toggle('active',x.id===id));document.body.classList.toggle('admin-mode',id==='admin');if(id==='customer'||id==='admin')activateRoleTheme(id);else S.activeRole=null;$('#aiPanel').classList.remove('open');closeSheets();if(id==='admin')showAdminView('dashboard');else window.scrollTo(0,0);if(id==='gateway')startGateway();if(id==='customer'){const greeting=$('.greeting');$('#customer').classList.toggle('is-guest',S.isGuest);greeting.textContent=S.isGuest?'Mode tamu · harga & stok terbuka':'Selamat datang kembali';greeting.classList.toggle('guest-mode-label',S.isGuest)}if(id==='customer'&&!S.isGuest&&!S.dailyCheckedIn){if(S.myCustomerDoc)runDailyCheckin();else{S.dailyCheckinPending=true;const st=$('#checkinStatus');if(st)st.textContent='Memuat…'}}}
function runDailyCheckin(){if(S.isGuest||S.dailyCheckedIn||!S.activeCustomerId||!S.myCustomerDoc)return;const statusEl=$('#checkinStatus');if(S.myCustomerDoc.lastCheckin===S.todayKey){S.dailyCheckedIn=true;if(statusEl)statusEl.textContent='Sudah diambil';return}if(!(S.coinProgramEnabled&&S.coinEvents.checkin&&S.coinRewards.checkin>0)){S.dailyCheckedIn=true;if(statusEl)statusEl.textContent='Nonaktif';return}Store.grantCoins(S.activeCustomerId,S.coinRewards.checkin,{reason:'harian',label:'Check-in harian',detail:'Bonus hari ini'}).then(()=>{S.dailyCheckedIn=true;if(statusEl)statusEl.textContent='Sudah diambil';setTimeout(()=>{celebrate('coin');toast('Bonus harian · +'+S.coinRewards.checkin+' Koin Warga')},180)}).catch(error=>{if(!error||error.code!=='OFFLINE')toast(error&&error.message?error.message:'Bonus harian gagal · bisa dicoba lagi')})}
function renderSessionInfo(){const role=S.sessionRole==='customer'?'Pelanggan':S.sessionRole==='admin'?'Admin':'Tamu',name=S.sessionName||(role==='Admin'?'Admin Warunge Mimi':role==='Tamu'?'Belum masuk':'Pelanggan'),time=S.sessionStartedAt?new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Jakarta',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(S.sessionStartedAt)).replace('.',':'):'Belum masuk';$('#sessionInfoRole').textContent=role;$('#sessionInfoName').textContent=name;$('#sessionInfoTime').textContent=time}

function bindProductDetails(){$$('[data-detail]').forEach(el=>{el.onclick=()=>openProduct(el.dataset.detail);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openProduct(el.dataset.detail)}}})}
function openProduct(id){const p=S.products.find(x=>x.id===id);if(!p)return;S.currentDetail=id;S.detailQty=1;$('#detailName').textContent=p.name;$('#detailPrice').textContent=money(p.price);$('#detailOldPrice').textContent=p.oldPrice?money(p.oldPrice):'';$('#detailPromo').hidden=!p.promo;$('#detailImg').src=p.img;$('#detailImg').alt=p.name;$('#detailStockBig').textContent=p.stock+' pcs';$('#detailWholesaleMini').textContent=p.wholesaleQty?money(p.wholesalePrice)+'/item':'-';$('#detailCat').textContent=p.cat||'-';$('#detailUnit').textContent=p.unit||'pcs';$('#detailQty').textContent='1';$('#detailTotal').textContent=money(p.price);$('#detailAlert').textContent=priceWatching(id)?'Harga dipantau':'Pantau harga';openSheet('productModal')}
function updateDetailTotal(){const p=S.products.find(x=>x.id===S.currentDetail);if(!p)return;const q=Math.max(1,S.detailQty||1);$('#detailQty').textContent=q;$('#detailTotal').textContent=money(p.price*q)}
function showDetailSlide(index){$$('.detail-slide').forEach((x,i)=>x.classList.toggle('active',i===index));$$('.slider-dot').forEach((x,i)=>x.classList.toggle('active',i===index))}

$('#gateway').addEventListener('click',event=>{if(event.target.closest('#gatewaySkip')||event.target.closest('#adminHotspot')||event.target.closest('[data-gateway-slide]'))return;if(S.gatewayJustSwiped){S.gatewayJustSwiped=false;return}advanceGateway()});
$('#gateway').addEventListener('touchstart',event=>{S.gatewayTouchX=event.changedTouches[0].clientX},{passive:true});
$('#gateway').addEventListener('touchend',event=>{const dx=event.changedTouches[0].clientX-S.gatewayTouchX;if(Math.abs(dx)<38)return;S.gatewayJustSwiped=true;if(dx<0)advanceGateway();else{showGatewaySlide(S.gatewayIndex-1,true);scheduleGateway()}},{passive:true});
$$('[data-gateway-slide]').forEach(button=>button.onclick=event=>{event.stopPropagation();showGatewaySlide(Number(button.dataset.gatewaySlide),true);scheduleGateway()});
$('#gatewaySkip').onclick=event=>{event.stopPropagation();enterGuestCustomer()};

function openAdminAccess(){stopGatewayTimer();const email=$('#adminLoginEmail'),password=$('#adminLoginPassword'),status=$('#adminLoginStatus');if(email)email.value='';if(password)password.value='';if(status){status.textContent='';status.className='auth-status'}openSheet('adminPinModal');setTimeout(()=>{const em=$('#adminLoginEmail');if(em)em.focus()},80)}
function enterAdminSession(message){go('admin');toast(message)}
$('#adminHotspot').onclick=event=>{event.stopPropagation();openAdminAccess()};
$('.customer-logo').addEventListener('click',event=>{event.stopPropagation();openAdminAccess()});
$('#adminLoginForm').addEventListener('submit',event=>{event.preventDefault();const email=normalizedEmail($('#adminLoginEmail').value),password=$('#adminLoginPassword').value,status=$('#adminLoginStatus');status.className='auth-status error';if(!email||!password){status.textContent='Lengkapi email dan kata sandi';return}status.className='auth-status';status.textContent='Menghubungkan…';Store.loginAdmin(email,password).then(()=>{status.className='auth-status success';status.textContent='Data cocok';closeSheets();enterAdminSession('Mode Admin dibuka');bioOfferEnroll(email,password,'admin')}).catch(error=>{status.className='auth-status error';status.textContent=error&&error.message?error.message:'Masuk gagal'})});
function addCustomerItem(id,amount){S.customerCart[id]=(S.customerCart[id]||0)+(amount||1);updateCustomerCart();toast(amount&&amount>1?'Semua bahan masuk keranjang':'Ditambahkan ke keranjang')}
function productMini(p,kind,opt){opt=opt||{};const qty=opt.qty||1,label=opt.label||p.short,price=p.price*qty,promo=opt.promo===false?false:p.promo;return `<article class="${kind}-card" data-detail="${p.id}" tabindex="0" role="button" aria-label="Lihat detail ${escapeHtml(label)}">${promo?'<span class="promo-flag">PROMO</span>':''}<img src="${p.img}" alt="${escapeHtml(label)}"><h3>${escapeHtml(label)}</h3><div class="price">${money(price)}</div>${opt.meta?`<small class="home-data-note">${escapeHtml(opt.meta)}</small>`:''}<button class="tiny-add" data-add-home="${p.id}" data-home-qty="${qty}" aria-label="Tambah ${escapeHtml(label)}">+</button></article>`}
function recipeTotal(recipe){return recipe.items.reduce((sum,item)=>{const product=S.products.find(p=>p.id===item.productId);return sum+(product?product.price*item.qty:0)},0)}
function recipeIngredientsText(recipe){return recipe.items.map(item=>{const product=S.products.find(p=>p.id===item.productId);return product?(product.name+' ×'+item.qty):''}).filter(Boolean).join(', ')}
function recipeCard(recipe,mine){const photo=recipe.foto?`<div class="recipe-photo"><img src="${recipe.foto}" alt="Foto resep ${escapeHtml(recipe.nama)}" loading="lazy"></div>`:'';return `<article class="recipe-card${recipe.foto?'':' no-photo'}">${photo}<div class="recipe-copy"><span class="recipe-label">${mine?'Resepku':'Warga'}</span><h3>${escapeHtml(recipe.nama)}</h3><p>${escapeHtml(recipe.desc)}</p><div class="recipe-actions"><button data-add-recipe="${recipe.id}" data-recipe-owner="${mine?'mine':'admin'}">+ Bahan</button><button class="recipe-share" data-share-recipe="${recipe.id}" data-recipe-owner="${mine?'mine':'admin'}" aria-label="Bagikan ${escapeHtml(recipe.nama)} ke Rumpi"><svg class="icon"><use href="#speaker"/></svg></button></div><small class="recipe-source">${escapeHtml(recipeIngredientsText(recipe))} · ${money(recipeTotal(recipe))}</small></div></article>`}
function findRecipe(id,owner){return (owner==='mine'?S.myRecipes:(S.recipes||[])).find(recipe=>recipe.id===id)}
