function renderAdminRecipeList(){const list=$('#adminRecipeList');if(!list)return;const recipes=S.recipes||[];list.innerHTML=recipes.map(recipe=>`<article class="control-recipe-item">${recipe.foto?`<img src="${recipe.foto}" alt="Foto resep ${escapeHtml(recipe.nama)}">`:'<span class="recipe-photo-empty" aria-label="Tanpa foto"><svg class="icon"><use href="#image"/></svg></span>'}<span><b>${escapeHtml(recipe.nama)}</b><small>${recipe.items.length} bahan · ${money(recipeTotal(recipe))}</small></span><span class="control-recipe-actions"><button data-edit-recipe="${recipe.id}" aria-label="Ubah ${escapeHtml(recipe.nama)}"><svg class="icon"><use href="#edit"/></svg></button><button data-delete-recipe="${recipe.id}" aria-label="Hapus ${escapeHtml(recipe.nama)}"><svg class="icon"><use href="#trash"/></svg></button></span></article>`).join('')||'<div class="notification-empty">Belum ada resep warga.</div>';$('#adminRecipeLimit').textContent=recipes.length+' dari maksimal 5 resep';$('#addAdminRecipe').disabled=recipes.length>=5;$$('[data-edit-recipe]').forEach(button=>button.onclick=()=>openAdminRecipeForm(button.dataset.editRecipe));$$('[data-delete-recipe]').forEach(button=>button.onclick=()=>storePromise('deleteRecipe',button.dataset.deleteRecipe).then(()=>toast('Resep dihapus dari Beranda pelanggan')).catch(error=>{if(!error||error.code!=='OFFLINE')toast(error&&error.message?error.message:'Hapus resep gagal')}))}
function renderAdminPromoList(){const list=$('#adminPromoList');if(!list)return;const promos=S.promosAdmin||[];list.innerHTML=promos.map(p=>{const on=p.isActive!==false;return `<article class="control-recipe-item"><span><b>${escapeHtml(p.title||'Promo')}</b><small>${escapeHtml(p.copy||'')}</small></span><span class="control-recipe-actions"><button class="toggle-btn" data-promo-toggle="${p.id}" aria-pressed="${on}">${on?'AKTIF':'NONAKTIF'}</button><button data-promo-delete="${p.id}" aria-label="Hapus ${escapeHtml(p.title||'promo')}"><svg class="icon"><use href="#trash"/></svg></button></span></article>`}).join('')||'<div class="notification-empty">Belum ada promo carousel.</div>';$$('[data-promo-toggle]').forEach(b=>b.onclick=()=>storePromise('setPromoActive',b.dataset.promoToggle,b.getAttribute('aria-pressed')!=='true').then(()=>toast('Status promo diperbarui')).catch(error=>{if(!error||error.code!=='OFFLINE')toast(error&&error.message?error.message:'Gagal memperbarui')}));$$('[data-promo-delete]').forEach(b=>b.onclick=()=>storePromise('deletePromo',b.dataset.promoDelete).then(()=>toast('Promo dihapus')).catch(error=>{if(!error||error.code!=='OFFLINE')toast(error&&error.message?error.message:'Hapus promo gagal')}))}
function productOptions(selected){return S.products.map(product=>`<option value="${product.id}"${product.id===selected?' selected':''}>${escapeHtml(product.name)}</option>`).join('')}
function addIngredientRow(containerId,item){const container=$('#'+containerId),row=document.createElement('div');row.className='ingredient-row';row.innerHTML=`<select aria-label="Pilih produk">${productOptions(item&&item.productId)}</select><input type="text" inputmode="numeric" value="${groupedNumber(item&&item.qty||1)}" aria-label="Jumlah bahan"><button type="button" aria-label="Hapus bahan"><svg class="icon"><use href="#trash"/></svg></button>`;row.querySelector('button').onclick=()=>{if(container.children.length===1)return toast('Minimal satu bahan');row.remove();updateIngredientSummary(containerId)};row.querySelectorAll('select,input').forEach(field=>field.oninput=()=>updateIngredientSummary(containerId));container.append(row);updateIngredientSummary(containerId)}
function ingredientItems(containerId){return [...$('#'+containerId).children].map(row=>({productId:row.querySelector('select').value,qty:Math.max(1,Number(row.querySelector('input').value)||1)}))}
function updateIngredientSummary(containerId){const items=ingredientItems(containerId),total=items.reduce((sum,item)=>{const product=S.products.find(p=>p.id===item.productId);return sum+(product?product.price*item.qty:0)},0),target=containerId==='adminRecipeIngredients'?'#adminRecipeSummary':'#myRecipeSummary';$(target).textContent=items.length+' bahan · perkiraan total '+money(total)}
function setRecipePhoto(kind,src,label){const preview=$(kind==='admin'?'#adminRecipePhotoPreview':'#myRecipePhotoPreview');if(kind==='admin')S.pendingAdminRecipePhoto=src;else S.pendingMyRecipePhoto=src;if(src)preview.src=src;else preview.removeAttribute('src');preview.alt='Pratinjau '+(label||'foto resep');preview.hidden=!src}
function resizeRecipePhoto(file,kind){const input=$(kind==='admin'?'#adminRecipePhotoInput':'#myRecipePhotoInput');if(!file.type.startsWith('image/')){input.value='';return toast('Pilih file gambar dari HP')}if(file.size>5*1024*1024){input.value='';return toast('Foto maksimal 5 MB')}const image=new Image(),objectUrl=URL.createObjectURL(file);image.onload=()=>{const maxSide=300,scale=Math.min(1,maxSide/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(image,0,0,canvas.width,canvas.height);setRecipePhoto(kind,canvas.toDataURL('image/png'),file.name);URL.revokeObjectURL(objectUrl);toast('Foto resep PNG siap · '+canvas.width+' × '+canvas.height+' px')};image.onerror=()=>{URL.revokeObjectURL(objectUrl);input.value='';toast('Foto tidak dapat dibaca')};image.src=objectUrl}
function setRumpiPhoto(kind,src){const wrap=kind==='admin'?$('#adminRumpiPhotoWrap'):$('#customerRumpiPhotoWrap'),preview=kind==='admin'?$('#adminRumpiPhotoPreview'):$('#customerRumpiPhotoPreview');if(kind==='admin')S.pendingAdminRumpiPhoto=src;else S.pendingCustomerRumpiPhoto=src;if(src)preview.src=src;else preview.removeAttribute('src');wrap.hidden=!src}
function resizeRumpiPhoto(file,kind){const input=kind==='admin'?$('#adminRumpiPhotoInput'):$('#customerRumpiPhotoInput');if(!file.type.startsWith('image/')){input.value='';return toast('Pilih file gambar dari HP')}if(file.size>5*1024*1024){input.value='';return toast('Foto maksimal 5 MB')}const image=new Image(),objectUrl=URL.createObjectURL(file);image.onload=()=>{const maxSide=300,scale=Math.min(1,maxSide/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(image,0,0,canvas.width,canvas.height);setRumpiPhoto(kind,canvas.toDataURL('image/png'));URL.revokeObjectURL(objectUrl);toast('Foto PNG siap · '+canvas.width+' × '+canvas.height+' px')};image.onerror=()=>{URL.revokeObjectURL(objectUrl);input.value='';toast('Foto tidak dapat dibaca')};image.src=objectUrl}
function openAdminRecipeForm(id){const recipes=S.recipes||[];if(!id&&recipes.length>=5)return toast('Maksimal 5 resep Ide Masak');S.editingRecipeId=id||null;const recipe=id?recipes.find(item=>item.id===id):null;$('#adminRecipeFormTitle').textContent=recipe?'Ubah Ide Masak':'Tambah Ide Masak';$('#adminRecipeName').value=recipe?recipe.nama:'';$('#adminRecipeDesc').value=recipe?recipe.desc:'';$('#adminRecipePhotoInput').value='';setRecipePhoto('admin',recipe&&recipe.foto?recipe.foto:'',recipe?recipe.nama:'foto resep');$('#adminRecipeIngredients').innerHTML='';(recipe?recipe.items:[{productId:(S.products[0]?S.products[0].id:''),qty:1}]).forEach(item=>addIngredientRow('adminRecipeIngredients',item));openSheet('adminRecipeModal')}
function openMyRecipeForm(){$('#myRecipeName').value='';$('#myRecipePhotoInput').value='';setRecipePhoto('mine','','foto resep');$('#myRecipeIngredients').innerHTML='';addIngredientRow('myRecipeIngredients',{productId:(S.products[0]?S.products[0].id:''),qty:1});openSheet('myRecipeModal')}
function purchaseAgeLabel(dateKey){const today=new Date(S.todayKey+'T12:00:00+07:00'),purchaseDate=new Date(dateKey+'T12:00:00+07:00'),days=Math.max(0,Math.round((today-purchaseDate)/86400000));return days===0?'Dibeli hari ini':days===1?'Dibeli kemarin':'Dibeli '+days+' hari lalu'}
function renderHome(){const restock=S.riwayatBelanjaPelanggan.map(entry=>({entry,product:S.products.find(product=>product.id===entry.productId)})).filter(row=>row.product).sort((a,b)=>a.entry.terakhirDibeli.localeCompare(b.entry.terakhirDibeli));const popular=S.penjualanGlobal.map(entry=>({entry,product:S.products.find(product=>product.id===entry.productId)})).filter(row=>row.product&&row.product.isActive!==false).sort((a,b)=>b.entry.totalTerjual-a.entry.totalTerjual).slice(0,8);$('#restockGrid').innerHTML=restock.length?restock.map(row=>productMini(row.product,'quick',{meta:purchaseAgeLabel(row.entry.terakhirDibeli)})).join(''):'<div class="empty-note">Belum ada riwayat belanja.</div>';$('#popularGrid').innerHTML=popular.length?popular.map(row=>productMini(row.product,'popular',{meta:row.entry.totalTerjual+' terjual'})).join(''):'<div class="empty-note">Belum ada data penjualan.</div>';$('#restockCountHint').textContent=restock.length?restock.length+' riwayat · geser →':'Belum ada riwayat';$('#popularCountHint').textContent=popular.length?popular.length+' teratas · geser →':'Belum ada data';$$('[data-add-home]').forEach(b=>b.onclick=e=>{e.stopPropagation();addCustomerItem(b.dataset.addHome,Number(b.dataset.homeQty)||1)});bindProductDetails();renderRecipes()}
function categoryNames(){return [...new Set(S.products.map(product=>product.cat).filter(Boolean))]}
function renderCategoryChips(){const customer=$('#customerCategories'),categories=categoryNames();if(!categories.includes(S.customerCat)&&S.customerCat!=='Semua')S.customerCat='Semua';if(!categories.includes(S.adminCat))S.adminCat='Semua';if(customer)customer.innerHTML=['Semua',...categories].map(cat=>`<button class="chip${cat===S.customerCat?' active':''}" data-cat="${escapeHtml(cat)}">${escapeHtml(cat)}</button>`).join('');if(customer)$$('[data-cat]').forEach(button=>button.onclick=()=>{S.customerCat=button.dataset.cat;renderCustomer()});const sel=$('#adminCategorySelect');if(sel){sel.innerHTML='<option value="Semua">Semua Kategori</option>'+categories.map(cat=>`<option value="${escapeHtml(cat)}"${cat===S.adminCat?' selected':''}>${escapeHtml(cat)}</option>`).join('');sel.onchange=()=>{S.adminCat=sel.value;renderAdminProducts()}}}
function renderCatalogHero(){const hero=$('#catalogHero');if(!hero)return;const fp=S.flashProductId?S.products.find(p=>p.id===S.flashProductId):null;if(!fp||fp.isActive===false){hero.hidden=true;return}hero.hidden=false;hero.innerHTML=`<small>PROMO KILAT · TERBATAS</small><h3>${escapeHtml(fp.name)}</h3><div class="kat-hero-price">${fp.oldPrice?'<s>'+money(fp.oldPrice)+'</s>':''}<b>${money(fp.price)}</b></div><button class="kat-hero-cta" data-detail="${fp.id}">Lihat Detail</button>`;bindProductDetails()}
function renderCatalogCats(){const box=$('#catalogCats');if(!box)return;const cats=categoryNames();box.innerHTML=['Semua',...cats].map(cat=>`<button class="kat-chip${S.customerCat===cat?' active':''}" data-cat="${escapeHtml(cat)}">${cat==='Semua'&&S.customerCat==='Semua'?'✓ ':''}${escapeHtml(cat)}</button>`).join('');box.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{S.customerCat=b.dataset.cat;renderCustomer()});const label=document.querySelector('#catalogSectionTitle span');if(label)label.textContent=S.customerCat==='Semua'?'Semua produk':S.customerCat}
function renderCustomer(){renderCatalogHero();renderCatalogCats();const q=$('#searchInput').value.toLowerCase();const shown=S.products.filter(p=>p.isActive!==false&&(S.customerCat==='Semua'||p.cat===S.customerCat)&&p.name.toLowerCase().includes(q));$('#customerProducts').innerHTML=shown.map(p=>`<article class="product-card" data-detail="${p.id}" tabindex="0" role="button" aria-label="Lihat detail ${p.name}">${p.promo?'<span class="promo-flag">PROMO</span>':''}<img src="${p.img}" alt="${p.name}"><div><h3>${p.name}</h3><div class="price">${money(p.price)}</div><small style="color:var(--muted)">Stok ${stockText(p)}</small></div><button class="add" data-add-c="${p.id}" aria-label="Tambah ${p.name}">+</button></article>`).join('');$('#emptyCustomer').hidden=shown.length>0;$$('[data-add-c]').forEach(b=>b.onclick=e=>{e.stopPropagation();addCustomerItem(b.dataset.addC)});bindProductDetails()}
function updateCustomerCart(){const count=Object.entries(S.customerCart).filter(([id,qty])=>qty>0&&S.products.some(p=>p.id===id)).reduce((sum,[,qty])=>sum+qty,0);$('#cartBadge').textContent=count;$('#cartBadge').hidden=count===0;renderCartPage()}
function setAuthTab(name){$$('[data-auth-tab]').forEach(button=>{const active=button.dataset.authTab===name;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active))});$('#loginAuthPanel').classList.toggle('active',name==='login');$('#registerAuthPanel').classList.toggle('active',name==='register');$('#loginAuthStatus').textContent='';$('#registerAuthStatus').textContent=''}
function setProfileIdentity(name){const safe=cleanInput(name)||'Pelanggan';$('#profileName').textContent=safe;$('#profileInitial').textContent=safe.charAt(0).toUpperCase();$('#customerNameInput').value=safe}
function requestGuestAccess(action){S.pendingGuestAction=action;const checkout=action==='checkout';$('#guestLockKicker').textContent=checkout?'Checkout khusus pelanggan':'Fitur khusus pelanggan';$('#guestLockTitle').textContent='Masuk / Daftar';$('#guestLockCopy').textContent='Mau lanjut? Login atau daftar dulu ya...';setAuthTab('login');openSheet('guestLoginModal');setTimeout(()=>$('#loginEmail').focus(),80)}
function requireCustomer(action){if(!S.isGuest)return false;requestGuestAccess(action);return true}
function openCheckoutDelivery(){if(requireCustomer('checkout'))return;S.fulfillment='pickup';S.coinRedeemEnabled=false;$$('#fulfillmentMethod button').forEach((b,i)=>b.classList.toggle('active',i===0));$('#deliveryFields').classList.remove('active');updateCheckoutSummary();openSheet('deliveryModal')}
function finishCustomerLogin(account){const action=S.pendingGuestAction;S.pendingGuestAction=null;S.isGuest=false;S.sessionRole='customer';S.activeCustomerId=account.id;S.sessionName=account.name;S.sessionStartedAt=new Date().toISOString();setProfileIdentity(account.name);go('customer');if(action==='chatCustomer'||action==='akunCustomer')goCustomer(action);else if(action==='checkout')openCheckoutDelivery();else if(action==='titip'){goCustomer('homeCustomer');openSheet('titipModal')}toast('Berhasil masuk sebagai '+account.name)}
function normalizedEmail(value){return String(value||'').trim().toLocaleLowerCase('id-ID')}
