function renderSavedMenu(){const area=$('#savedMenuArea');if(!S.savedMenu){area.innerHTML='';return}const count=Object.values(S.savedMenu).reduce((a,b)=>a+b,0);area.innerHTML=`<section class="saved-menu"><div><b>Menu belanja rumah</b><small>${count} barang · tersimpan selama sesi ini</small></div><button id="useSavedMenu">Gunakan</button></section>`;$('#useSavedMenu').onclick=()=>{S.customerCart=Object.assign({},S.savedMenu);updateCustomerCart();toast('Menu tersimpan dimasukkan')}}
