function adminAiResponse(query){const q=String(query||'').toLocaleLowerCase('id-ID').trim();if(!q)return 'Tulis pertanyaan singkat tentang data sesi ini.';const named=S.products.find(product=>q.includes(product.name.toLocaleLowerCase('id-ID'))||q.includes(product.short.toLocaleLowerCase('id-ID')));if(named&&/(stok|sisa|tersedia|habis)/.test(q))return named.name+' tersisa '+stockText(named)+' '+(named.unit||'pcs')+(named.stock<=S.lowStockThreshold?' · sudah masuk prioritas restok.':' · stok masih di atas batas menipis '+S.lowStockThreshold+'.');if(/transaksi|jurnal|riwayat/.test(q))return adminAiTransactions();if(/omzet|omset|penjualan|laba|untung/.test(q))return adminAiSales();if(/stok|restok|kulak|menipis|kritis|habis/.test(q))return adminAiStock();if(/arus kas|saldo|kas|uang masuk|uang keluar/.test(q))return adminAiCash();if(/pelanggan|pendaftaran|warga baru/.test(q))return adminAiCustomers();return 'Saya belum memahami pertanyaan itu. Coba tanyakan “omzet hari ini”, “transaksi apa saja hari ini”, “stok apa yang menipis”, “saldo kas”, atau nama produk tertentu.'}
